import{_t as e,it as t,n,rt as r}from"./chunks/framework.XJu5filh.js";import"./chunks/assets.DWopfgZq.js";var i=JSON.parse(`{"title":"队伍信息","description":"","frontmatter":{},"headers":[],"relativePath":"feature/party.md","filePath":"feature/party.md","lastUpdated":1792333409000}`),a={name:`feature/party.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="队伍信息" tabindex="-1">队伍信息 <a class="header-anchor" href="#队伍信息" aria-label="Permalink to “队伍信息”">​</a></h1><p>通常使用游戏页面分享编成时，至少需要截图三次，非常繁琐。而且角色的FA技能开关情况还有武器的插件都不能很好的展示。</p><p>为了解决这个问题，太郎在进入编成界面时获取数据并整理展示。桌面与扩展可通过顶部工具栏复制或下载配置图片，也可打开角色详情和配置对比。移动端展示队伍及技能效果，不提供该工具栏。</p><p><img src="/tarou-docs/assets/img/party-img1.png" alt="alt text" width="309" height="701"></p><h2 id="获取角色fa技能状态" tabindex="-1">获取角色FA技能状态 <a class="header-anchor" href="#获取角色fa技能状态" aria-label="Permalink to “获取角色FA技能状态”">​</a></h2><p>角色的FA技能状态需要进入角色详情页面才可以获取并保存在本地，这样以后就能直接读取。</p><p>FA 技能信息保存在当前设备。如果通过其他设备修改了游戏中的开关，需要在当前设备再次进入对应详情页更新。</p><p>主角同理，不过主角的技能FA开关是通过颜色来区别的，灰色代表没有开启，橘色代表开启。</p><h2 id="获取友招信息" tabindex="-1">获取友招信息 <a class="header-anchor" href="#获取友招信息" aria-label="Permalink to “获取友招信息”">​</a></h2><p><img src="/tarou-docs/assets/img/party-img2.png" alt="alt text" width="312" height="76"></p><p>友招比较特别，需要点击预测伤害设置页面才能获取到。</p><h2 id="获取角色详情" tabindex="-1">获取角色详情 <a class="header-anchor" href="#获取角色详情" aria-label="Permalink to “获取角色详情”">​</a></h2><p><img src="/tarou-docs/assets/img/party-img3.png" alt="alt text" width="350" height="497"></p><p>第一张图中还有个没有展示出来的信息，那就是角色详情，包括神器信息以及戒指和耳环属性。</p><p>神器信息在角色详情页就可以获得，戒指和耳环则需要点进【能力强化】页面才能获取。</p><p>获取完毕之后，鼠标悬浮在角色上就会展示详情信息，同时还会有一个W标识的按钮，点击可以打开角色对应的中文wiki页面。</p><h2 id="配置对比" tabindex="-1">配置对比 <a class="header-anchor" href="#配置对比" aria-label="Permalink to “配置对比”">​</a></h2><p>桌面与扩展在队伍信息顶部工具栏点击“配置对比”按钮，可打开对比窗口，查看不同队伍配置的技能差别。下图为旧版入口示意。</p><p><img src="/tarou-docs/assets/img/party-img4.png" alt="alt text" width="1071" height="695"></p><p>顶部高亮表示的<code>当前配置</code>会实时映射当前游戏中的队伍信息，点击切换。当两个配置都有数据时，会自动开始对比技能数据。</p><p><img src="/tarou-docs/assets/img/party-img5.png" alt="alt text" width="1022" height="731"></p>`,21)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};